using namespace dome;
namespace {thread_local bool active=false;thread_local long cut=-1;thread_local size_t allocations=0,hits=0;size_t checks=0;}
void*operator new(size_t n){if(active){++allocations;if(cut==0){++hits;throw std::bad_alloc();}if(cut>0)--cut;}if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](size_t n){return ::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,size_t)noexcept{std::free(p);}void operator delete[](void*p,size_t)noexcept{std::free(p);}
namespace {
void check(bool b,const char*why){if(!b)throw std::runtime_error(why);++checks;}
template<class F>void reject(F f,const char*why){try{f();}catch(const std::exception&){++checks;return;}throw std::runtime_error(why);}
ImportedImage png(uint32_t width,std::array<uint8_t,4>color){std::vector<uint8_t>pixels;for(size_t x=0;x<width;++x)pixels.insert(pixels.end(),color.begin(),color.end());png_image im{};im.version=PNG_IMAGE_VERSION;im.width=width;im.height=1;im.format=PNG_FORMAT_RGBA;png_alloc_size_t count=0;if(!png_image_write_to_memory(&im,nullptr,&count,0,pixels.data(),0,nullptr))throw std::runtime_error("PNG fixture size");ImportedImage out;out.name="Actual PNG";out.mime_type="image/png";out.bytes.resize(count);if(!png_image_write_to_memory(&im,out.bytes.data(),&count,0,pixels.data(),0,nullptr))throw std::runtime_error("PNG fixture data");out.bytes.resize(count);return out;}
ImportedImage jpeg(){jpeg_compress_struct c{};jpeg_error_mgr errors{};c.err=jpeg_std_error(&errors);jpeg_create_compress(&c);unsigned char*bytes=nullptr;unsigned long count=0;jpeg_mem_dest(&c,&bytes,&count);c.image_width=c.image_height=1;c.input_components=3;c.in_color_space=JCS_RGB;jpeg_set_defaults(&c);jpeg_start_compress(&c,TRUE);unsigned char pixel[]{17,81,139};JSAMPROW row=pixel;jpeg_write_scanlines(&c,&row,1);jpeg_finish_compress(&c);ImportedImage image;image.name="Actual JPEG";image.mime_type="image/jpeg";image.bytes.assign(bytes,bytes+count);jpeg_destroy_compress(&c);std::free(bytes);return image;}
}
int main()try{
 const auto red=png(1,{101,17,33,97}),blue=png(1,{9,201,81,255}),green=png(1,{37,41,211,123});std::vector<ImportedImage>aliases(256,red);for(size_t i=0;i<aliases.size();++i){aliases[i].name="Distinct original "+std::to_string(i);aliases[i].source_uri="distinct-"+std::to_string(i)+".png";}const auto source=aliases;auto decoded=detail::decode_source_images(aliases,1);check(decoded->size()==256,"Alias-expanded bounded records retain every image slot under the unchanged unique-pixel budget");for(auto&p:*decoded)if(p!=decoded->front())throw std::runtime_error("Exact encoded aliases allocated different pixel owners");check(decoded->front()->rgba==std::vector<uint8_t>({101,17,33,97}),"Exact native RGBA and fractional alpha remain unchanged");check(aliases[0].name!=aliases[1].name&&aliases[0].bytes==source[0].bytes&&aliases[255].source_uri==source[255].source_uri,"All distinct names/URIs/encoded records remain immutable and independent");
 auto two=detail::decode_source_images(std::array{red,blue},2);check(two->at(0)!=two->at(1)&&two->at(1)->rgba==std::vector<uint8_t>({9,201,81,255}),"Different encoded bytes own different exact decoded leaves");reject([&]{detail::decode_source_images(std::array{red,blue,green},2);},"A distinct near-budget image must refuse before decoded allocation");reject([&]{detail::decode_source_images(std::array{red,png(2,{1,2,3,4})},2);},"Different dimensions must count their complete distinct resource");auto mime=red;mime.mime_type="image/jpeg";reject([&]{detail::decode_source_images(std::array{red,mime},2);},"Equal bytes with different MIME must not reuse a decoded PNG leaf");auto invalid=red;invalid.bytes[16]=0;invalid.bytes[17]=0;invalid.bytes[18]=32;invalid.bytes[19]=1;reject([&]{detail::decode_source_images(std::array{red,invalid},64*1024*1024);},"Every record retains its dimension validation even near aliases");auto jpg=jpeg();auto formats=detail::decode_source_images(std::array{red,jpg,jpg},2);check(formats->at(0)!=formats->at(1)&&formats->at(1)==formats->at(2),"Core JPEG has its own validated pixel owner and exact JPEG aliases reuse it");aliases.push_back(red);reject([&]{detail::decode_source_images(aliases,1);},"Descriptor count remains independently bounded despite exact aliases");reject([&]{detail::decode_source_images(std::span<const ImportedImage>{},0);},"Zero pixel budget must refuse");reject([&]{detail::decode_source_images(std::span<const ImportedImage>{},64*1024*1024+1);},"The64M unique-owned-pixel cap is unchanged");
 const std::array input{red,red,blue};size_t calls=0;detail::decode_source_images(input,2,[&]{++calls;return false;});for(size_t boundary=1;boundary<=calls;++boundary){size_t now=0;reject([&]{detail::decode_source_images(input,2,[&]{return ++now>=boundary;});},"Every measured decode/cache cancellation boundary must refuse");}
 allocations=hits=0;cut=-1;active=true;detail::decode_source_images(input,2);active=false;const size_t measured=allocations;for(size_t boundary=0;boundary<measured;++boundary){allocations=hits=0;cut=long(boundary);active=true;bool failed=false;try{detail::decode_source_images(input,2);}catch(const std::bad_alloc&){failed=true;}catch(...){active=false;throw;}active=false;cut=-1;check(failed&&hits,"Every measured persistent allocation denial propagates actual bad_alloc without mutating input");check(input[0].bytes==red.bytes&&input[1].mime_type==red.mime_type&&input[2].bytes==blue.bytes,"Failure retains exact encoded inputs and source slot metadata");}
 std::cout<<checks<<" decoded-source-image checks; cancellation="<<calls<<" persistent="<<measured<<'\n';return 0;
}catch(const std::exception&e){active=false;std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
